<template>
  <mars-dialog :title="`空间分析｜${result.alertNo}`" icon="map-distance" custom-class="alert-analysis-result-dialog spatial-result-dialog" :visible="true" :width="920" top="64" :draggable="true" :nopadding="true" :persist-layout="false" @closed="emit('close')">
    <div class="spatial-page">
      <header class="spatial-summary"><div><div class="result-kicker">异常点空间分布</div><h2>{{ result.taskName }}</h2><p>按接口 points[] 的真实经纬度、温差与确认状态展示</p></div><span class="point-count">{{ result.metrics.total }} 个有效点</span></header>
      <section class="metric-strip" aria-label="异常点统计"><div><span>点位总数</span><strong>{{ result.metrics.total }}</strong></div><div><span>待确认</span><strong>{{ result.metrics.pending }}</strong></div><div><span>已确认</span><strong>{{ result.metrics.confirmed }}</strong></div><div><span>最大温差</span><strong class="is-hot">{{ temperature(result.metrics.maxDiffC,true) }}</strong></div><div><span>最小温差</span><strong class="is-cold">{{ temperature(result.metrics.minDiffC,true) }}</strong></div><div><span>平均温差</span><strong>{{ temperature(result.metrics.averageDiffC,true) }}</strong></div></section>
      <div class="spatial-layout">
        <section class="map-panel"><div class="panel-heading"><div><h3>点位分布示意</h3><p>坐标按当前点集范围等比例投影；该视图不代表异常边界或影响范围。</p></div><div class="map-legend"><span class="hot">正温差</span><span class="cold">负温差</span><span class="confirmed">已确认</span></div></div>
          <svg class="spatial-canvas" viewBox="0 0 620 370" role="img" aria-label="异常点空间分布图"><defs><pattern id="point-grid" width="31" height="31" patternUnits="userSpaceOnUse"><path d="M31 0L0 0 0 31" fill="none" stroke="rgba(139,176,201,.08)" /></pattern></defs><rect width="620" height="370" fill="url(#point-grid)" /><text class="axis-label" x="12" y="20">北 ↑</text><g v-for="point in plottedPoints" :key="point.id" class="point-marker" :class="[point.diff_c != null && point.diff_c >= 0 ? 'is-hot' : 'is-cold', { 'is-confirmed': point.confirmed }]"><circle :cx="point.x" :cy="point.y" :r="point.radius" /><path v-if="point.confirmed" :d="`M ${point.x-4} ${point.y} l3 3 6 -7`" /><title>{{ point.id }}｜{{ temperature(point.diff_c,true) }}｜{{ point.confirmed?'已确认':'待确认' }}</title></g><text class="extent-label" x="18" y="354">{{ result.extent.minLng.toFixed(4) }}°E</text><text class="extent-label" x="602" y="354" text-anchor="end">{{ result.extent.maxLng.toFixed(4) }}°E</text></svg>
        </section>
        <aside class="facts-panel"><h3>分布概况</h3><dl><div><dt>经度范围</dt><dd>{{ result.extent.minLng.toFixed(4) }}—{{ result.extent.maxLng.toFixed(4) }}</dd></div><div><dt>纬度范围</dt><dd>{{ result.extent.minLat.toFixed(4) }}—{{ result.extent.maxLat.toFixed(4) }}</dd></div><div><dt>异常指数</dt><dd>{{ result.anomalyIndex ?? "—" }}</dd></div><div><dt>趋势字段</dt><dd>{{ result.trend }}</dd></div></dl><p>{{ result.summary }}</p></aside>
      </div>
      <section class="point-table"><div class="panel-heading"><div><h3>异常点明细</h3><p>点击地图点可核对对应编号，状态仅使用接口 confirmed 字段。</p></div></div><div class="table-scroll"><table><thead><tr><th>点位编号</th><th>日期</th><th>经度</th><th>纬度</th><th>温差</th><th>确认状态</th></tr></thead><tbody><tr v-for="point in result.points" :key="point.id"><td>{{ point.id }}</td><td>{{ point.date }}</td><td>{{ point.lon.toFixed(5) }}</td><td>{{ point.lat.toFixed(5) }}</td><td :class="point.diff_c != null && point.diff_c >= 0 ? 'is-hot' : 'is-cold'">{{ temperature(point.diff_c,true) }}</td><td><span class="status-chip" :class="{ 'is-confirmed':point.confirmed }">{{ point.confirmed?'已确认':'待确认' }}</span></td></tr></tbody></table></div></section>
    </div>
    <template #footer><div class="result-footer"><button data-testid="close-spatial-result" type="button" @click="emit('close')">返回告警确认</button></div></template>
  </mars-dialog>
</template>

<script setup lang="ts">
import { computed } from "vue"
import type { SpatialAnalysisResult } from "./analysis-model"
const props = defineProps<{result:SpatialAnalysisResult}>(); const emit = defineEmits<{(event:"close"):void}>()
const plottedPoints = computed(() => { const e = props.result.extent; const width = Math.max(e.maxLng - e.minLng, 0.0001); const height = Math.max(e.maxLat - e.minLat, 0.0001); const max = Math.max(...props.result.points.map(p => Math.abs(p.diff_c || 0)), 1); return props.result.points.map(p => ({ ...p, x: 48 + (p.lon - e.minLng) / width * 524, y: 40 + (1 - (p.lat - e.minLat) / height) * 278, radius: 5 + Math.abs(p.diff_c || 0) / max * 5 })) })
function temperature(value:number|null, signed = false) { return value == null ? "—" : `${signed && value > 0 ? "+" : ""}${Number(value.toFixed(3))}℃` }
</script>

<style lang="less" scoped>
.spatial-page{max-height:calc(100vh - 150px);overflow-y:auto;padding:22px;color:var(--text-primary,#eef5fb);background:linear-gradient(180deg,rgba(27,55,65,.34),transparent 190px),var(--popup-bg,#0d141b)}.spatial-summary{display:flex;justify-content:space-between;gap:24px;align-items:flex-start;padding-bottom:18px;border-bottom:1px solid rgba(151,185,210,.16)}.result-kicker{color:#75c8b2;font-size:12px}h2{margin:4px 0;font-size:20px}.spatial-summary p,.panel-heading p{margin:0;color:rgba(220,235,246,.58);font-size:12px}.point-count{padding:7px 12px;border:1px solid rgba(100,199,161,.35);border-radius:4px;color:#7bd9b4;background:rgba(100,199,161,.1);font-size:13px;font-weight:600}.metric-strip{display:grid;grid-template-columns:repeat(6,1fr);gap:1px;margin:16px 0;border:1px solid rgba(151,185,210,.14);background:rgba(151,185,210,.14)}.metric-strip div{padding:12px;background:rgba(15,25,34,.96)}.metric-strip span{display:block;color:rgba(220,235,246,.55);font-size:11px}.metric-strip strong{display:block;margin-top:6px;font-size:15px}.spatial-layout{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(220px,.65fr);gap:14px}.map-panel,.facts-panel,.point-table{padding:16px;border:1px solid rgba(151,185,210,.14);background:rgba(16,27,36,.72)}.panel-heading{display:flex;justify-content:space-between;gap:14px;margin-bottom:12px}h3{margin:0 0 3px;font-size:14px}.map-legend{display:flex;gap:10px;color:rgba(220,235,246,.65);font-size:10px}.map-legend span::before{content:"";display:inline-block;width:8px;height:8px;margin-right:4px;border-radius:50%}.map-legend .hot::before{background:#ff805e}.map-legend .cold::before{background:#58b5ed}.map-legend .confirmed::before{border:2px solid #fff;background:transparent}.spatial-canvas{display:block;width:100%;min-height:330px;border:1px solid rgba(151,185,210,.12);background:#0b151c}.point-marker circle{stroke:rgba(255,255,255,.5);stroke-width:1}.point-marker.is-hot circle{fill:rgba(255,128,94,.82)}.point-marker.is-cold circle{fill:rgba(88,181,237,.82)}.point-marker.is-confirmed circle{stroke:#fff;stroke-width:2.5}.point-marker path{fill:none;stroke:#fff;stroke-width:1.6}.axis-label,.extent-label{fill:rgba(220,235,246,.52);font-size:10px}.facts-panel dl{margin:12px 0}.facts-panel dl div{padding:9px 0;border-bottom:1px solid rgba(151,185,210,.1)}dt{color:rgba(220,235,246,.5);font-size:10px}dd{margin:4px 0 0;color:#9dd7c5;font-size:12px}.facts-panel p{margin:14px 0 0;color:rgba(238,247,255,.72);font-size:12px;line-height:1.7}.point-table{margin-top:14px}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:12px}th{color:rgba(220,235,246,.55);font-weight:500;text-align:left;background:rgba(151,185,210,.06)}th,td{padding:9px 10px;border-bottom:1px solid rgba(151,185,210,.1)}.is-hot{color:#ff987c}.is-cold{color:#70c5f5}.status-chip{display:inline-block;padding:2px 7px;border-radius:10px;color:#f3b377;background:rgba(255,156,74,.12)}.status-chip.is-confirmed{color:#7bd9b4;background:rgba(100,199,161,.12)}.result-footer{display:flex;justify-content:flex-end;width:100%;padding:10px 16px;border-top:1px solid rgba(151,185,210,.14);background:#0d141b}.result-footer button{height:32px;padding:0 16px;border:1px solid rgba(65,168,255,.52);border-radius:4px;background:rgba(65,168,255,.14);color:#8fd0ff;cursor:pointer}@media(max-width:800px){.metric-strip{grid-template-columns:repeat(2,1fr)}.spatial-layout{grid-template-columns:1fr}.spatial-page{padding:14px}}
</style>
